Lemma objI_agree_d : forall (M M' : word -> option byte) V S2 dI dD dI' dD', 0 <= V -> V + ENC_SIZE <= 2 ^ 64 ->
  EKA.agree M M' V O_STACK -> EKA.agree M M' (V + O_COLON) (O_DEPTH - O_COLON) -> L5.defined M' V ENC_SIZE ->
